
local bit32 = bit32
local KEY = {132,4,129,220,111,123,16,212,103,86,255,34,69,207,215,38,255,9,204,191,129,240,182,152,85,109,3,230,125,227,207,105}
local DATA_B64 = ""

local b64chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local map = {}
for i = 1, #b64chars do
    map[string.sub(b64chars, i, i)] = i - 1
end

local function base64decode(s)
    local out = {}
    local buffer, bits = 0, 0

    for i = 1, #s do
        local c = string.sub(s, i, i)
        if c ~= "=" then
            local v = map[c]
            if v then
                buffer = bit32.bor(bit32.lshift(buffer, 6), v)
                bits += 6
                if bits >= 8 then
                    bits -= 8
                    out[#out + 1] = string.char(bit32.band(bit32.rshift(buffer, bits), 255))
                    buffer = bit32.band(buffer, bit32.lshift(1, bits) - 1)
                end
            end
        end
    end

    return table.concat(out)
end

local encrypted = base64decode(DATA_B64)
local chars = table.create(#encrypted)

for i = 1, #encrypted do
    local b = string.byte(encrypted, i)
    local k = KEY[((i - 1) % #KEY) + 1]
    chars[i] = string.char(bit32.bxor(b, k))
end

local source = table.concat(chars)
local fn, err = loadstring(source)

if not fn then
    error("Encrypted payload failed to load: " .. tostring(err))
end

return fn()
